/**
 * Generate build-time configuration for premium features
 *
 * This script generates a TypeScript file with build constants
 * based on environment variables. The TypeScript compiler will
 * eliminate dead code branches, removing premium code from free builds.
 */

const fs = require('fs');
const path = require('path');

// Read environment variable
// Every feature is free and included in every build.
const isPremiumBuild = true;
const buildType = process.env.BUILD_TYPE || 'production';

// Generate TypeScript file content
const content = `/**
 * Build Configuration (Auto-generated)
 *
 * ⚠️ DO NOT EDIT THIS FILE MANUALLY
 * Generated by scripts/generate-build-config.js
 *
 * Build type: ${buildType}
 * Premium features: ${isPremiumBuild ? 'ENABLED' : 'DISABLED'}
 */

/**
 * Build-time constant controlling premium feature availability
 * - Free builds: false (premium code removed by TypeScript + minifier)
 * - Premium builds: true (premium code included)
 * - This constant is replaced at build time based on BUILD_PREMIUM env variable
 */
export const PREMIUM_FEATURES_AVAILABLE = ${isPremiumBuild};

/**
 * Build type identifier
 */
export const BUILD_TYPE = '${buildType}' as const;

/**
 * Build timestamp
 */
export const BUILD_TIMESTAMP = ${Date.now()};
`;

// Write to src/core/build-config.ts
const outputPath = path.join(__dirname, '..', 'src', 'core', 'build-config.ts');
fs.writeFileSync(outputPath, content, 'utf8');

console.log(`✓ Generated build configuration: ${buildType}`);
console.log(`  Premium features: ${isPremiumBuild ? 'ENABLED' : 'DISABLED'}`);
console.log(`  Output: ${outputPath}`);
